#include "ksSerialSetupCalls.h"
#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{SerialSetupPartialTest partialTest=nullptr;using T=SerialSetupTask;using S=T::Stage;using K=T::Kind;using P=T::Port;struct Point{unsigned location,length;};Point point(const T&t){switch(t.stage()){case S::Disable:return{0xfbc,2};case S::WriteDisable:return{0xfbe,2};case S::Mode:return{0xfc0,2};case S::WriteMode:return{0xfc2,2};case S::Baud:return{0xfc4,2};case S::WriteBaud:return{0xfc6,2};case S::Hold:return{0xfc8,2};case S::SetDelay:return{0xfca,4};case S::Tick:return{0xfce,2};case S::AdmitDelay:return{0xfd0,2};case S::Restore:return{0xfd2,2};case S::Finish:return{t.kind()==K::Configure?0xfd4u:0xfe2u,2};case S::Enable:return{0xfd6,2};case S::WriteEnable:return{0xfd8,2};case S::DispatchRx:return{0xfda,4};case S::AwaitRx:case S::DispatchTx:return{0xfde,4};case S::AwaitTx:return{0xfe2,2};default:throw std::runtime_error("Invalid serial setup stage");}}unsigned address(P p){return p==P::Control?0xffff8a:p==P::Mode?0xffff88:0xffff89;}}
bool SerialSetupCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0xfbc||pc==0xfd6){if(selected)throw std::runtime_error("Overlapping serial setup");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Serial setup capacity");selected->emplace(pc==0xfbc?K::Configure:K::Start,h.getSP());++started;}if(!selected||point((**selected).task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;if(t.awaiting())t.resumeChild();auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(t).length);auto&v=h.regs;auto clock=[&](P p){auto at=address(p);return (at&1)&&h.lastwrite==int(at-1)?0u:1u;};auto cost=t.nextClocks(clock);t.advanceBefore(cost,[&](P p,uint8_t value){f.store8(address(p),int8_t(value));},clock);switch(stage){case S::Disable:case S::Mode:f.move(v[0].rl,0);break;case S::Baud:f.move(v[0].rl,0x18);break;case S::Enable:f.move(v[0].rl,0x70);break;case S::Hold:f.push(v[0].r);(**selected).depth+=2;break;case S::SetDelay:f.move(v[0].r,100);break;case S::Tick:f.inc(v[0].r,-1);break;case S::Restore:f.pop(v[0].r);(**selected).depth-=2;break;case S::DispatchRx:case S::DispatchTx:f.call(stage==S::DispatchRx?0xfe4:0x10e4);h.pc=h.makepc(f.next);break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::DispatchRx&&stage!=S::DispatchTx&&stage!=S::Finish)h.pc=h.makepc(point(t).location);if(h.cycles-before!=cost)throw std::runtime_error("Serial setup clocks differ");return true;}}

namespace ks{void setSerialSetupPartialForTests(SerialSetupPartialTest fn){partialTest=fn;}}
